begin;
-- Disposable/rolled-back fixtures. Never use genuine employees or wallets.
insert into public.tenants(tenant_id,business_name) values('91111111-1111-4111-8111-111111111111','Logistics SQL fixture A'),('81111111-1111-4111-8111-111111111111','Logistics SQL fixture B');
insert into auth.users(id,email,is_anonymous) values('92222222-2222-4222-8222-222222222222','logistics-sql-a@example.invalid',false),('82222222-2222-4222-8222-222222222222','logistics-sql-b@example.invalid',false);
insert into public.user_profiles(user_id,tenant_id,email) values('92222222-2222-4222-8222-222222222222','91111111-1111-4111-8111-111111111111','logistics-sql-a@example.invalid'),('82222222-2222-4222-8222-222222222222','81111111-1111-4111-8111-111111111111','logistics-sql-b@example.invalid');
insert into public.roles(tenant_id,role_id,name) values('91111111-1111-4111-8111-111111111111','94444444-4444-4444-8444-444444444444','OWNER'),('81111111-1111-4111-8111-111111111111','84444444-4444-4444-8444-444444444444','OWNER');
insert into public.role_permissions select r.tenant_id,r.role_id,p.permission_id from public.roles r cross join public.permissions p where r.tenant_id in ('91111111-1111-4111-8111-111111111111','81111111-1111-4111-8111-111111111111');
insert into public.user_roles values('91111111-1111-4111-8111-111111111111','92222222-2222-4222-8222-222222222222','94444444-4444-4444-8444-444444444444'),('81111111-1111-4111-8111-111111111111','82222222-2222-4222-8222-222222222222','84444444-4444-4444-8444-444444444444');
create function pg_temp.employee_assert(ok boolean,msg text) returns void language plpgsql as $$ begin if ok is not true then raise exception 'FAIL: %',msg; end if; end $$;
create function pg_temp.employee_reject(q text,expected text) returns void language plpgsql as $$ begin
 begin execute q; exception when others then if position(lower(expected) in lower(sqlerrm))=0 then raise exception 'Expected %; got %',expected,sqlerrm; end if; return; end;
 raise exception 'Expected rejection: %',expected; end $$;
grant execute on function pg_temp.employee_assert(boolean,text),pg_temp.employee_reject(text,text) to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','92222222-2222-4222-8222-222222222222',true);
do $$ declare d uuid; h uuid; d2 uuid; v uuid; tr uuid; newer uuid; cash uuid; bank uuid; body jsonb; result jsonb; req uuid; payment uuid;
 today date:=(now() at time zone 'Asia/Dhaka')::date; baseline numeric; revision integer; i integer; p uuid; plant uuid; brand uuid; item uuid;
begin
 d:=(public.save_employee('{"name":"Logistics Driver One","phones":[{"phone":"01700000101","is_primary":true}],"business_unit":"truck_business","employee_type_name":"Driver","terms":{"monthly_salary":20000,"effective_from":"2025-01-01","is_active":true}}',gen_random_uuid())->>'employee_id')::uuid;
 d2:=(public.save_employee('{"name":"Logistics Driver Two","phones":[{"phone":"01700000102","is_primary":true}],"business_unit":"truck_business","employee_type_name":"Driver","terms":{"monthly_salary":20000,"effective_from":"2025-01-01","is_active":true}}',gen_random_uuid())->>'employee_id')::uuid;
 h:=(public.save_employee('{"name":"Logistics Helper","phones":[{"phone":"01700000103","is_primary":true}],"business_unit":"truck_business","employee_type_name":"Helper","terms":{"monthly_salary":10000,"effective_from":"2025-01-01","is_active":true}}',gen_random_uuid())->>'employee_id')::uuid;
 body:='{"name":"Logistics Vehicle One","serial_no":"LOG-SQL-ONE","capacity":1}'; req:=gen_random_uuid();
 result:=public.save_vehicle(body,req); v:=(result->>'vehicle_id')::uuid;
 perform pg_temp.employee_assert(public.save_vehicle(body,req)=result,'vehicle creation idempotent');
 perform pg_temp.employee_assert(public.get_vehicle(v)->>'location'='Home','new location is Home');
 perform pg_temp.employee_reject(format('select public.create_custom_transit(%L,%L)',jsonb_build_object('vehicle_id',v,'fee',1000,'client_name','Logistics client','destination','Dhaka'),gen_random_uuid()),'Assign a Driver');
 body:=jsonb_build_object('vehicle_id',v,'revision',2,'name','Logistics Vehicle One','serial_no','LOG-SQL-ONE','capacity',1,'driver_employee_id',h);
 perform pg_temp.employee_reject(format('select public.save_vehicle(%L,%L)',body,gen_random_uuid()),'Driver');
 body:=body||jsonb_build_object('driver_employee_id',d,'helper_employee_id',h); perform public.save_vehicle(body,gen_random_uuid());
 perform pg_temp.employee_reject(format('select public.save_vehicle(%L,%L)',body,gen_random_uuid()),'changed');
 perform pg_temp.employee_reject(format('select public.save_vehicle(%L,%L)',jsonb_build_object('name','Double assignment','serial_no','DOUBLE','capacity',0,'driver_employee_id',d),gen_random_uuid()),'another vehicle');
 body:=jsonb_build_object('vehicle_id',v,'fee',1000,'client_name','Logistics client','destination','Dhaka'); req:=gen_random_uuid(); result:=public.create_custom_transit(body,req); tr:=(result->>'transit_id')::uuid;
 perform pg_temp.employee_assert(public.create_custom_transit(body,req)=result,'client fee exact once after replay');
 perform pg_temp.employee_assert(public.get_vehicle(v)->>'location'='Dhaka','destination derived from active transit');
 perform pg_temp.employee_assert(public.get_transit(tr)->>'driver_employee_id'=d::text and public.get_transit(tr)->>'helper_employee_id'=h::text,'crew captured at departure');
 select wallet_id into cash from public.get_trip_payment_wallets(tr) where type='cash'; select wallet_id into bank from public.get_trip_payment_wallets(tr) where type='dealership';
 select sum(balance) into baseline from public.wallets;
 perform public.save_transit_costs(tr,'{"driver_cost":500,"helper_cost":100,"oil_cost":50,"others_cost":20,"additional_costs":[{"name":"Toll","amount":30}]}',1);
 perform pg_temp.employee_assert((select sum(balance) from public.wallets)=baseline,'earnings are deferred with no wallet posting');
 perform pg_temp.employee_assert((public.get_logistics_summary(null,d)->>'outstanding')::numeric=500,'employee outstanding earning');
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',d,'kind','trips','trip_count',1,'transit_id',tr,'trip_role','driver','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',100),jsonb_build_object('wallet_id',bank,'amount',200)))));
 req:=gen_random_uuid(); result:=public.employee_payment_operation(body,req); payment:=(result->'payment_ids'->>0)::uuid;
 perform pg_temp.employee_assert(public.employee_payment_operation(body,req)=result,'split employee payment exact once');
 perform pg_temp.employee_assert((public.get_transit(tr)->>'outstanding')::numeric=400,'partial balance is correct');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',jsonb_set(body,'{items,0,employee_id}',to_jsonb(d2)),gen_random_uuid()),'recorded on this transit');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',body,gen_random_uuid()),'exceeds');
 perform pg_temp.employee_reject(format('select public.transition_transit(%L,%L,3)',tr,'complete'),'outstanding');
 perform pg_temp.employee_reject(format('select public.save_transit_costs(%L,%L,3)',tr,'{"driver_cost":200,"helper_cost":100,"oil_cost":50,"others_cost":0}'),'below employee payments');
 perform public.transition_transit(tr,'return',3);
 perform pg_temp.employee_assert(public.get_vehicle(v)->>'location'='Home','return frees vehicle before payment');
 perform public.save_vehicle(jsonb_build_object('vehicle_id',v,'revision',3,'name','Logistics Vehicle One','serial_no','LOG-SQL-ONE','capacity',1,'driver_employee_id',d2,'helper_employee_id',null),gen_random_uuid());
 perform pg_temp.employee_assert(public.get_transit(tr)->>'driver_employee_id'=d::text and public.get_transit(tr)->>'helper_employee_id'=h::text,'reassignment preserves historical crew');
 newer:=(public.create_custom_transit(jsonb_build_object('vehicle_id',v,'fee',0,'client_name','Later client','destination','Chattogram'),gen_random_uuid())->>'transit_id')::uuid;
 perform pg_temp.employee_assert(public.get_transit(newer)->>'driver_employee_id'=d2::text,'next departure uses new crew');
 perform pg_temp.employee_reject(format('select public.save_transit_costs(%L,%L,1)',newer,'{"driver_cost":0,"helper_cost":100,"oil_cost":0,"others_cost":0}'),'recorded Helper');
 body:=jsonb_set(body,'{items,0,payments}',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',200))); perform public.employee_payment_operation(body,gen_random_uuid());
 body:=jsonb_set(jsonb_set(jsonb_set(body,'{items,0,employee_id}',to_jsonb(h)),'{items,0,trip_role}','"helper"'),'{items,0,payments}',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',100))); perform public.employee_payment_operation(body,gen_random_uuid());
 perform public.employee_payment_operation(jsonb_build_object('action','reverse_payment','payment_id',payment,'payment_date',today,'reason','Funds returned for SQL fixture'),gen_random_uuid());
 perform pg_temp.employee_reject(format('select public.transition_transit(%L,%L,7)',tr,'complete'),'outstanding');
 body:=jsonb_set(jsonb_set(jsonb_set(body,'{items,0,employee_id}',to_jsonb(d)),'{items,0,trip_role}','"driver"'),'{items,0,payments}',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',300))); perform public.employee_payment_operation(body,gen_random_uuid());
 perform public.record_operating_payment(jsonb_build_object('transit_id',tr,'kind','expense','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',100))),gen_random_uuid());
 perform public.transition_transit(tr,'complete',9); perform public.transition_transit(tr,'complete',9);
 perform pg_temp.employee_assert((select sum(balance) from public.wallets)=baseline-700,'crew plus non-crew posted exactly once');
 perform pg_temp.employee_assert(public.get_vehicle(v)->>'location'='Chattogram','old completion cannot release a later journey');
 perform pg_temp.employee_assert((public.get_logistics_summary(null,d)->>'paid')::numeric=500 and (public.get_logistics_summary(null,d)->>'outstanding')::numeric=0,'employee earnings reconcile after returns');
 perform pg_temp.employee_assert((public.get_employee_salary_month(d,date_trunc('month',today)::date)->>'paid')::numeric=0,'transit earnings stay separate from salary');
 perform pg_temp.employee_assert((public.get_employee_activity(jsonb_build_object('employee_id',d,'kind','transit'))->>'total')::int>0,'transit participation in unified activity');
 perform pg_temp.employee_reject(format('select public.employee_payment_operation(%L,%L)',body,gen_random_uuid()),'open operating costs');
 perform public.transition_transit(newer,'complete',1);
 perform public.save_vehicle(jsonb_build_object('vehicle_id',v,'revision',4,'name','Logistics Vehicle One','serial_no','LOG-SQL-ONE','capacity',0,'driver_employee_id',null,'helper_employee_id',null),gen_random_uuid());
 perform pg_temp.employee_assert(public.get_vehicle(v)->>'driver_employee_id' is null,'unlink current crew');
 perform pg_temp.employee_assert((public.get_vehicle_assignments(jsonb_build_object('vehicle_id',v))->>'total')::int=3,'complete assignment history retained');
 perform pg_temp.employee_assert((public.get_vehicle_directory('{"search":"LOG-SQL"}',0,1)->>'total')::int=1,'server vehicle search and pagination');
 perform pg_temp.employee_assert((public.get_transit_directory(jsonb_build_object('employee_id',d,'status','completed'),0,1)->>'total')::int=1,'server employee and status filtering');
 -- Purchase dispatch, receipt, deferred payables and final completion share the same crew rules.
 perform public.save_vehicle(jsonb_build_object('vehicle_id',v,'revision',5,'name','Logistics Vehicle One','serial_no','LOG-SQL-ONE','capacity',0,'driver_employee_id',d2),gen_random_uuid());
 brand:=(public.create_lpg_brand('Logistics purchase brand',null)->>'brand_id')::uuid;
 plant:=(public.create_gas_plant('Logistics filling plant',brand,'Dhaka')->>'plant_id')::uuid;
 insert into public.items(tenant_id,brand_id,size_kg,mouth_size) values('91111111-1111-4111-8111-111111111111',brand,12,'22mm') returning item_id into item;
 p:=(public.create_purchase(jsonb_build_object('plant_id',plant,'request_id',gen_random_uuid()))->>'purchase_id')::uuid;
 perform public.update_purchase(p,jsonb_build_object('vehicle_id',v,'commission',0,'transport_cost',20,'labour_cost',0,'notes','Purchase fixture','items',jsonb_build_array(jsonb_build_object('item_id',item,'type','package','quantity',10,'unit_price',100))),1);
 perform public.dispatch_purchase(p,2);
 select transit_id into tr from public.transits where purchase_id=p;
 perform pg_temp.employee_assert(public.get_vehicle(v)->>'location'='Logistics filling plant','purchase destination automatic');
 perform public.save_transit_costs(tr,'{"driver_cost":100,"helper_cost":0,"oil_cost":20,"others_cost":0}',1);
 perform public.receive_purchase(p,3);
 perform pg_temp.employee_assert(public.get_vehicle(v)->>'location'='Home','receipt frees vehicle with unpaid earnings');
 perform pg_temp.employee_reject(format('select public.transition_transit(%L,%L,3)',tr,'complete'),'outstanding');
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',d2,'kind','trips','trip_count',1,'transit_id',tr,'trip_role','driver','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',100)))));
 perform public.employee_payment_operation(body,gen_random_uuid()); perform public.record_operating_payment(jsonb_build_object('transit_id',tr,'kind','expense','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',20))),gen_random_uuid()); perform public.transition_transit(tr,'complete',5);
 perform pg_temp.employee_assert((select filled_quantity from public.items where item_id=item)=10,'purchase receipt quantity exceeds informational capacity without restriction');
 -- Cancellation refunds client funding while incurred employee earnings remain due.
 tr:=(public.create_custom_transit(jsonb_build_object('vehicle_id',v,'fee',100,'client_name','Cancelled earnings fixture','destination','Dhaka'),gen_random_uuid())->>'transit_id')::uuid;
 perform public.save_transit_costs(tr,'{"driver_cost":200,"helper_cost":0,"oil_cost":20,"others_cost":0}',1);
 body:=jsonb_build_object('action','pay','items',jsonb_build_array(jsonb_build_object('employee_id',d2,'kind','trips','trip_count',1,'transit_id',tr,'trip_role','driver','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',100)))));
 perform public.employee_payment_operation(body,gen_random_uuid()); perform public.transition_transit(tr,'cancel',3);
 perform pg_temp.employee_assert((public.get_transit(tr)->>'outstanding')::numeric=120,'cancelled incurred earnings remain due');
 perform pg_temp.employee_reject(format('select public.transition_transit(%L,%L,4)',tr,'complete'),'outstanding');
 perform public.employee_payment_operation(body,gen_random_uuid()); perform public.record_operating_payment(jsonb_build_object('transit_id',tr,'kind','expense','payment_date',today,'payments',jsonb_build_array(jsonb_build_object('wallet_id',cash,'amount',20))),gen_random_uuid()); perform public.transition_transit(tr,'complete',6);
 perform pg_temp.employee_assert(public.get_transit(tr)->>'status'='cancelled' and public.get_transit(tr)->>'closed_at' is not null,'cancelled financial completion keeps operational evidence');
 for i in 1..27 loop
  tr:=(public.create_custom_transit(jsonb_build_object('vehicle_id',v,'fee',0,'client_name','History fixture '||i,'destination','Dhaka'),gen_random_uuid())->>'transit_id')::uuid;
  perform public.transition_transit(tr,'complete',1);
 end loop;
 result:=public.get_transit_directory(jsonb_build_object('search','History fixture','employee_id',d2,'vehicle_id',v,'status','completed','type','custom','from',today,'to',today),25,25);
 perform pg_temp.employee_assert((result->>'total')::integer=27 and jsonb_array_length(result->'entries')=2,'server transit search/status/type/crew/date filters apply before pagination');
 for i in 1..10 loop
  perform public.save_vehicle(public.get_vehicle(v)||jsonb_build_object('driver_employee_id',null),gen_random_uuid());
  perform public.save_vehicle(public.get_vehicle(v)||jsonb_build_object('driver_employee_id',d2),gen_random_uuid());
 end loop;
 result:=public.get_vehicle_assignments(jsonb_build_object('employee_id',d2,'status','ended','from',today,'to',today),8,8);
 perform pg_temp.employee_assert((result->>'total')::integer>=10 and jsonb_array_length(result->'entries')>0,'historical assignment filtering and pagination');
 perform pg_temp.employee_reject(format('select public.get_vehicle_assignments(%L,0,0)','{}'),'Invalid');
 perform set_config('request.jwt.claim.sub','82222222-2222-4222-8222-222222222222',true);
 perform pg_temp.employee_reject(format('select public.get_vehicle(%L)',v),'not found');
 perform pg_temp.employee_reject(format('select public.get_transit(%L)',tr),'not found');
 perform pg_temp.employee_assert((public.get_transit_directory(jsonb_build_object('vehicle_id',v))->>'total')::int=0,'foreign transit history empty');
 perform pg_temp.employee_assert((public.get_vehicle_assignments(jsonb_build_object('vehicle_id',v))->>'total')::int=0,'foreign assignment history empty');
end $$;
reset role;
select pg_temp.employee_assert(not exists(select 1 from public.wallets w where tenant_id='91111111-1111-4111-8111-111111111111' and w.balance<>coalesce((select sum(amount) from public.wallet_transactions x where x.tenant_id=w.tenant_id and x.wallet_id=w.wallet_id),0)),'wallet reconciliation');
select pg_temp.employee_assert(not exists(select 1 from public.employee_payment_entries e join public.employee_payments p using(tenant_id,payment_id) left join public.wallet_transactions w on w.tenant_id=e.tenant_id and w.employee_entry_id=e.entry_id where e.tenant_id='91111111-1111-4111-8111-111111111111' and (w.transaction_id is null or abs(w.amount)<>e.amount or (w.amount>0)<>(p.reversal_of is not null))),'one signed posting per employee payment entry');
select pg_temp.employee_assert(to_regclass('public.trucks') is null and to_regprocedure('public.list_transits()') is null and not exists(select 1 from information_schema.columns where table_schema='public' and table_name='vehicles' and column_name in ('size','location')),'obsolete fleet contracts removed');
select 'PASS: vehicle CRUD/assignments/history, mandatory driver, deferred/split/partial payments, returns, exact-once completion, purchase receipt, wallet reconciliation and tenant isolation';


rollback;
